{
  "case_id": "xsu_sg_005_work_capacity_scope",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Konklusionen stemmer med rubrikken og vejledningen: målestokken er erhvervsevne som uddannelsessøgende, og kommunal arbejdsevnevurdering, arbejdsprøvning, særlig arbejdspladsindretning, arbejdsgiverkontakt, studierelevans, lokale forhold og erhvervsevne efter uddannelsen indgår ikke. Ingen af rubrikkens materielle fejl begås. Udsagnet om skånehensyn ved andre jobtyper er ikke i strid med rubrikken."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle fem kritiske elementer er dækket i substans. Svaret nævner ikke udtrykkeligt 'funktionsnedsættelsens art og grad' eller 'svært ved at finde arbejde', men 'ressourcer', 'meget betydelige begrænsninger' og 'beskæftigelsessituationen indgår ikke' er tilsvarende formuleringer."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret tager hvert af de syv punkter i spørgsmålet op enkeltvis med et klart ja/nej. Afsnittet om, hvad der indgår, er relevant supplerende information."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret har fodnotehenvisninger og en kildeliste med SU-loven og vejledning nr. 10157, så de væsentlige udsagn kan knyttes til identificerbare kilder."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "Vejledning nr. 10157 er gyldig og autoritativ. Lovhenvisningen er derimod til LBK nr. 395 af 2023, § 7, stk. 1, nr. 1. Den frosne aktuelle bestemmelse er SU-loven § 7, stk. 3 (aktuel 2026-version), så henvisningen er til en forkert bestemmelse og en ikke-aktuel udgave."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "De fleste nej-udsagn understøttes af vejledningspassagerne. Udsagnet om 'meget betydelige begrænsninger' er knyttet til § 7, stk. 1, nr. 1, som ikke indeholder denne regel. Udsagnet om, at man ser på 'andre typer arbejde, evt. med skånehensyn eller i mindre omfang', støttes ikke af de viste passager, som kun nævner arbejdets karakter i forhold til funktionsnedsættelsen."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer, at man ser på, om andre typer arbejde kan varetages 'evt. med skånehensyn eller i mindre omfang' og 'ud fra sagens øvrige oplysninger'. Det har ikke støtte i de frosne passager. Rubrikken nævner skånehensyn som et supplerende element, men ikke 'i mindre omfang'."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Målestokken 'som uddannelsessøgende' og skellet til efter endt uddannelse er bevaret. Svaret siger, at tidligere arbejde 'kan' indgå, og at kommunal arbejdsevnevurdering ikke kan sammenlignes. Det udelukker ikke skånehensyn generelt."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Trinene er indbyrdes konsistente: først målestokken, derefter punkt for punkt hvad der ikke indgår, derefter hvad der indgår, og til sidst en konklusion, der følger heraf."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'Kan indgå' om tidligere arbejde og de kategoriske 'nej' om udelukkelserne gengiver kilden. Formuleringen 'Det mest nærliggende er derfor' i konklusionen er en unødig afdæmpning af en kategorisk udelukkelse, men ændrer ikke den juridiske betydning væsentligt."
    }
  },
  "xhaile_coverage": {
    "A15": {
      "label": "yes",
      "reason": "Svaret dækker kernen i punktet: der tages udelukkende stilling til evnen til erhvervsarbejde med de ressourcer, personen har, og meget betydelige begrænsninger er målestokken. Arbejdsprøvning, særlig arbejdspladsindretning, arbejdsgiverkontakt, studierelevans, lokale forhold, beskæftigelsessituationen og erhvervsevne efter uddannelsen indgår ikke. Ordblindeeksemplet og 'svært ved at finde arbejde' er ikke nævnt eksplicit, men det er ikke afgørende for punktets betydning."
    }
  },
  "overall_notes": "Den juridiske substans er korrekt og fuldstændig i forhold til rubrikken. Svagheden ligger i kilderne: den viste lovhenvisning (LBK 395/2023 § 7, stk. 1, nr. 1) passer ikke til den frosne aktuelle bestemmelse (§ 7, stk. 3), og passagen om 'skånehensyn eller i mindre omfang' har ikke støtte i de leverede vejledningspassager. Derfor er C05, C06 og C07 not_met."
}

